import { MeshStandardNodeMaterial } from 'three/webgpu';
import {
  texture,
  mix,
  dot,
  normalize,
  viewDirectionNode,
  normalWorldNode,
  pow,
  color
} from 'three/tsl';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as text from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;

  // Root group for this node
  const root = new Group();

  // Geometry (tessellated plane)
  const geometry = new PlaneGeometry(4, 0.8, 64, 64);

  // Base material (machined‑metal PBR)
  const material = new MeshStandardNodeMaterial({
    color: new Color('#0b0b10'), // surface
    metalness: 0.3,
    roughness: 0.6,
    clearcoat: 0.1
  });

  // Displacement node (depth map)
  let displacementNode = null;
  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
      displacementNode = texture(tex);
      material.displacementNode = displacementNode;
      material.displacementScale = 0.2;
      material.needsUpdate = true;
    });
  }

  // Color map (image)
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Rim‑light via emissive node (accent red)
  const rimNode = mix(
    color('#000000'),
    color('#ff2a38'),
    pow(
      1.0 - dot(normalize(viewDirectionNode), normalize(normalWorldNode)),
      2.0
    )
  );
  material.emissiveNode = rimNode;
  material.emissiveIntensity = 1.0;

  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Store timelines for cleanup
  const timelines = [];

  // Interaction handlers
  const handlers = {};

  // Hover – rise‑in effect (0.15 scene units)
  handlers.hover = () => {
    const tl = gsap.timeline();
    tl.to(mesh.position, {
      y: mesh.position.y + 0.15,
      duration: 0.7,
      ease: 'power3.out'
    });
    timelines.push(tl);
  };
  // Hover out – revert
  handlers.hoverOut = () => {
    const tl = gsap.timeline();
    tl.to(mesh.position, {
      y: mesh.position.y - 0.15,
      duration: 0.7,
      ease: 'power3.out'
    });
    timelines.push(tl);
  };
  // Click – emit navigation event
  handlers.click = () => {
    ctx.emit('navigate', { to: 'hub-pricing' });
  };

  root.userData.handlers = handlers;

  // Apply cinematic primitives from config
  const primitiveInstances = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const instance = ctx.primitives[prim.name](
        root,
        { ...prim.params, trigger: prim.trigger }
      );
      primitiveInstances.push(instance);
    }
  }

  // Cleanup routine
  root.userData.cleanup = () => {
    material.dispose();
    geometry.dispose();
    for (const tl of timelines) tl.kill();
    for (const p of primitiveInstances) p.cleanup();
  };

  return root;
}
